data.grammar_fragment:
agg<bigint>
  : <1> SUM "(" DISTINCT expr<int> ")"
  ;

agg<numeric>
  : <1> AVG "(" DISTINCT expr<int> ")"
  | <1> SUM "(" DISTINCT expr<bigint> ")"
  ;

self_join @frame
  : <2> "(" @table(t1) (JOIN | LEFT JOIN) @table(t1) USING "(" "c0" ")" ")"
  ;

set_stmt
  : <1> SET LOCAL "enable_self_join_elimination" "=" (ON | OFF)
  ;
